#include "LinkSmoke.h"
#include "VehicleState.h"
#include "protocol/VehicleProtocol.h"
#include <QGuiApplication>
#include <QQuickWindow>
#include <QQuickItem>
#include <QQmlEngine>
#include <QProcess>
#include <QDir>
#include <QFileInfo>
#include <QTimer>
#include <QUuid>
#include <QtTest>
#include <functional>
#include <stdexcept>

void runLinkSmoke(QGuiApplication &app,QQuickWindow &window,VehicleState &state,QStringList &warnings){
    window.setProperty("testMode",true);window.setProperty("clockText","16:28");
    QTimer::singleShot(1200,&app,[&]{
        window.showNormal();window.raise();window.requestActivate();
        QProcess simulator;QLocalSocket console;QByteArray buffer;QHash<QString,QJsonObject> replies;QJsonObject consoleState;
        const QString directory=qEnvironmentVariable("CAR_TERMINAL_LINK_OUTPUT","artifacts/link/smoke");QDir().mkpath(directory);
        auto require=[](bool ok,const char *message){if(!ok)throw std::runtime_error(message);};
        auto wait=[&](std::function<bool()> condition,const char *message,int timeout=6000){for(int i=0;!condition()&&i<timeout/20;++i)QTest::qWait(20);require(condition(),message);};
        std::function<QQuickItem*(QQuickItem*,const QString&)> find;find=[&](QQuickItem *p,const QString &name)->QQuickItem*{if(p->objectName()==name&&p->isVisible())return p;for(auto *c:p->childItems())if(auto *v=find(c,name))return v;return nullptr;};
        auto item=[&](const char *name){auto *v=find(window.contentItem(),QString::fromLatin1(name));require(v,name);return v;};
        auto click=[&](const char *name){auto *v=item(name);require(v->isEnabled(),name);QTest::mouseClick(&window,Qt::LeftButton,Qt::NoModifier,v->mapToScene(QPointF(v->width()/2,v->height()/2)).toPoint());QTest::qWait(70);};
        auto capture=[&](const QString &name){window.setProperty("toastMessage","");window.setProperty("feedbackQueue",QVariantList{});QTest::qWait(300);const auto shot=window.grabWindow();require(shot.save(directory+"/"+name+".png"),"save integration capture");return shot;};
        QObject::connect(&console,&QLocalSocket::readyRead,&app,[&]{buffer+=console.readAll();QList<QJsonObject> messages;QString error;if(!VehicleProtocol::decode(buffer,messages,error))return;for(const auto &m:messages){if(m["type"]=="controlResult")replies[m["id"].toString()]=m;else if(m["type"]=="snapshot")consoleState=m["state"].toObject();}});
        const QString serverName="qml-cockpit-test-"+QUuid::createUuid().toString(QUuid::WithoutBraces);
        auto connectConsole=[&]{console.abort();buffer.clear();consoleState={};for(int i=0;i<40&&console.state()!=QLocalSocket::ConnectedState;++i){console.connectToServer(serverName);if(!console.waitForConnected(100))QTest::qWait(50);}require(console.state()==QLocalSocket::ConnectedState,"operator pipe connection");console.write(VehicleProtocol::encode({{"type","hello"},{"role","operator"}}));wait([&]{return !consoleState.isEmpty();},"operator receives snapshot");};
        auto control=[&](const QString &action,QJsonObject args=QJsonObject{}){const auto id=QUuid::createUuid().toString();console.write(VehicleProtocol::encode({{"type","control"},{"id",id},{"action",action},{"args",args}}));wait([&]{return replies.contains(id);},"operator control result");const auto reply=replies.take(id);require(reply["ok"].toBool(),qPrintable(reply["reason"].toString()));};
        auto stopSimulator=[&]{simulator.terminate();if(!simulator.waitForFinished(2500)){simulator.kill();simulator.waitForFinished(2000);}};
        try{
            const QString executable=qEnvironmentVariable("QML_COCKPIT_SIMULATOR_EXE");require(QFileInfo::exists(executable),"set QML_COCKPIT_SIMULATOR_EXE to built simulator");
            simulator.setProgram(executable);simulator.setArguments({"--headless","--server",serverName});simulator.start();require(simulator.waitForStarted(3000),"launch real simulator process");connectConsole();
            state.connection()->setServerName(serverName);const auto local=state.snapshot();click("sourceButton");click("sourceExternal");wait([&]{return state.externalReady();},"external handshake");capture("01-connected");click("closePopup");
            control("soc",{{"value",37.5}});wait([&]{return std::abs(state.batteryPercent()-37.5)<0.01;},"external SOC updates cockpit");capture("02-external-soc");
            control("setDoor",{{"index",0},{"open",true}});wait([&]{return state.doors()[0].toBool();},"external door state");click("simulatorButton");click("startDriving");wait([&]{return state.connection()->lastCommand().contains(QStringLiteral("已拒绝"));},"door interlock returns rejected result");require(state.parked(),"rejection does not optimistically drive");
            control("closeDoors");QTest::qWait(750);click("startDriving");wait([&]{return state.gear()=="D"&&state.speed()==40&&window.property("page").toInt()==4;},"accepted driving enters scene asynchronously");control("setSpeed",{{"value",65}});wait([&]{return state.speed()==65;},"simulator speed updates cockpit");auto *drive=item("drivingVehicleScene");wait([&]{return drive->property("ready").toBool();},"driving renderer ready",8000);QTest::qWait(450);capture("03-live-driving");
            click("statusEnergyButton");require(window.property("page").toInt()==2&&state.gear()=="D"&&state.speed()==65,"battery details do not change driving state");click("tab0");click("homeDriving");require(window.property("page").toInt()==4&&state.speed()==65,"resume driving view preserves speed");
            control("park");wait([&]{return state.parked();},"remote park");click("tab2");auto *scene=item("controlsVehicleScene");wait([&]{return scene->property("ready").toBool();},"vehicle renderer ready",8000);click("vehicleSection1");
            control("window",{{"index",0},{"value",0}});click("windowPreset50");wait([&]{return state.windowTargets()[0].toInt()==50;},"target confirmed by simulator");require(state.windowActual()[0].toDouble()<50,"actual does not jump to requested target");capture("04-window-moving");wait([&]{return state.windows()[0].toInt()==50&&!state.windowBusy()[0].toBool()&&state.connection()->pendingCount()==0;},"window completion reply");
            click("windowPreset100");QTest::qWait(250);click("stopWindow");wait([&]{return !state.windowBusy()[0].toBool()&&state.connection()->pendingCount()==0;},"stop confirmed");const auto stopped=state.windowActual()[0].toDouble();require(stopped>50&&stopped<100,"stop actual midway");QTest::qWait(150);require(state.windowActual()[0].toDouble()==stopped,"old request cannot resume after stop");
            const int values[4]={0,15,50,100};for(int i=0;i<4;++i){const auto choose=QString("windowSelect%1").arg(i).toLatin1(),preset=QString("windowPreset%1").arg(values[i]).toLatin1();click(choose.constData());click(preset.constData());wait([&]{return state.windows()[i].toInt()==values[i]&&!state.windowBusy()[i].toBool();},"all four windows round trip");}
            click("windowSelect0");control("window",{{"index",0},{"value",22}});wait([&]{return state.windows()[0].toInt()==22;},"operator injected actual window");require(std::abs(scene->property("windowLF").toDouble()-0.22)<0.001,"actual simulator value drives glass mesh");QTest::qWait(500);capture("05-window-confirmed");
            control("faults",{{"reject",true}});click("windowPreset100");wait([&]{return state.connection()->lastCommand().contains(QStringLiteral("已拒绝"));},"rejected command status");require(state.windows()[0].toInt()==22,"rejected window keeps actual value");control("faults",{{"reject",false},{"drop",true}});click("windowPreset50");wait([&]{return state.connection()->lastCommand().contains(QStringLiteral("超时"));},"dropped request times out");require(state.windows()[0].toInt()==22,"timeout does not fake success");capture("06-timeout");
            control("faults",{{"drop",false},{"delayMs",400}});click("windowPreset50");require(state.windows()[0].toInt()==22,"delayed command waits for remote acceptance");wait([&]{return state.windows()[0].toInt()==50&&!state.windowBusy()[0].toBool();},"delayed command executes");control("faults",{{"delayMs",0}});
            control("faults",{{"delayMs",2300}});click("windowPreset100");wait([&]{return state.connection()->lastCommand().contains(QStringLiteral("超时"));},"late execution first reports request timeout");wait([&]{return state.windows()[0].toInt()==100&&!state.windowBusy()[0].toBool();},"telemetry reflects execution after request timed out");require(state.connection()->pendingCount()==0,"late reply does not resurrect expired request");control("faults",{{"delayMs",0}});
            click("vehicleSection5");click("chargePort");wait([&]{return state.portOpen();},"remote charge port");click("chargePlug");wait([&]{return state.plugged();},"remote plug confirmation");state.setChargeTarget(50);wait([&]{return state.chargeTarget()==50;},"remote charging target");click("chargeStart");wait([&]{return state.charging()&&state.chargePower()==55;},"remote charging power");const auto beforeCharge=state.batteryPercent();click("chargeFastForward");wait([&]{return state.batteryPercent()>beforeCharge+7;},"remote charge fast forward");capture("06b-charging");state.advanceSimulation(3600);wait([&]{return !state.charging()&&state.batteryPercent()==50;},"target SOC automatically stops charging");click("chargePlug");wait([&]{return !state.plugged();},"remote unplug");click("chargePort");wait([&]{return !state.portOpen();},"remote charge port closed");
            click("chargePort");wait([&]{return state.portOpen();},"open port for charge visualization");click("chargePlug");wait([&]{return state.plugged();},"connect for charge visualization");
            auto *energy=qmlEngine(scene)->singletonInstance<QObject*>("CarTerminal","EnergyVisual");require(energy,"shared energy presentation state");
            require(!scene->findChild<QObject*>("modelEnergyBadge"),"model energy card removed from shared scene");
            auto modelDifference=[&](const QImage &a,const QImage &b){
                const double pixelScale=double(a.width())/window.width();const auto area=scene->mapRectToScene(QRectF(0,170,scene->width(),scene->height()-170));
                const QRect roi(qRound(area.x()*pixelScale),qRound(area.y()*pixelScale),qRound(area.width()*pixelScale),qRound(area.height()*pixelScale));int changed=0;
                for(int y=roi.top();y<=roi.bottom()&&y<a.height();++y)for(int x=roi.left();x<=roi.right()&&x<a.width();++x){const auto p=a.pixelColor(x,y),q=b.pixelColor(x,y);if(std::abs(p.red()-q.red())+std::abs(p.green()-q.green())+std::abs(p.blue()-q.blue())>25)++changed;}
                return changed;
            };
            struct BandCase{double soc;const char *band;};
            for(const auto &test:QList<BandCase>{{0,"critical"},{10,"critical"},{10.1,"low"},{20,"low"},{20.1,"normal"},{79.9,"normal"},{80,"high"},{99.9,"high"},{99.99,"high"},{100,"full"}}){
                control("soc",{{"value",test.soc}});wait([&]{return std::abs(state.batteryPercent()-test.soc)<0.001;},"SOC boundary snapshot");require(energy->property("band").toString()==test.band,"SOC color band boundary");
                require(item("statusBattery")->property("text").toString()==QString::number(int(test.soc))+"%","top SOC uses conservative integer precision");
                if(test.soc>=99.9&&test.soc<100)require(item("chargeSocLabel")->property("text")=="99.9%","fractional SOC is not reported full");
            }
            control("soc",{{"value",5}});wait([&]{return state.batteryPercent()==5;},"low SOC");click("chargeStart");wait([&]{return state.charging();},"low SOC charging");require(scene->property("energyFlowRunning").toBool()&&item("chargeStateLabel")->property("text")==QStringLiteral("正在充电"),"visible charge flow and right panel status");const auto flowingModel=capture("energy-01-low-charging");QTest::qWait(350);require(modelDifference(flowingModel,window.grabWindow())>50,"energy animation changes visible model pixels");
            click("chargeStart");wait([&]{return !state.charging();},"pause flow");require(!scene->property("energyFlowRunning").toBool()&&energy->property("mode")=="connected","paused mode has no charge flow");const auto pausedModel=capture("energy-02-paused");require(modelDifference(flowingModel,pausedModel)>3000,"charging and paused model visibly differ outside labels");QTest::qWait(350);require(modelDifference(pausedModel,window.grabWindow())<50,"paused model energy effect remains still");click("tab0");require(item("homeEnergyRow")->property("chargeMode")=="connected","home paused summary");capture("home-energy-paused");click("homeViewCharging");
            control("soc",{{"value",45}});wait([&]{return state.batteryPercent()==45;},"normal SOC");click("chargeStart");wait([&]{return state.charging();},"normal SOC charging");capture("energy-03-normal-charging");click("chargeStart");wait([&]{return !state.charging();},"pause normal charging");
            control("soc",{{"value",5}});wait([&]{return state.batteryPercent()==5;},"low SOC for nearby stations");const auto lowColor=item("chargeSocLabel")->property("color");click("chargeNearbyStations");require(item("nearbyChargeSoc")->property("color")==lowColor,"nearby stations use the same low SOC color");capture("layout-nearby-low");click("closePopup");
            state.setChargeTarget(90);wait([&]{return state.chargeTarget()==90;},"raise target");control("soc",{{"value",85}});wait([&]{return state.batteryPercent()==85;},"high SOC");click("chargeStart");wait([&]{return state.charging();},"high SOC charging");capture("energy-04-high-charging");click("vehicleSection0");click("tab0");require(item("homeEnergyRow")->property("chargeMode")=="charging","home inline energy summary");require(!find(window.contentItem(),"modelEnergyBadge"),"home does not show a floating energy card");require(item("homeDate")->property("text")==window.property("dateText"),"home date does not repeat charging status");capture("energy-05-home-charging");state.setThemeMode("night");capture("energy-05b-night-charging");state.setThemeMode("day");click("homeBodyAlerts");require(window.property("popup")=="notifications","inline summary preserves body alerts");click("closePopup");click("homeViewCharging");require(window.property("page").toInt()==2&&item("chargeStart"),"view charging opens the charging controls");
            for(int section=0;section<6;++section){
                const auto name=QString("vehicleSection%1").arg(section).toLatin1();click(name.constData());QTest::qWait(300);
                require(!scene->findChild<QObject*>("modelEnergyBadge"),"no model energy card in any vehicle category");
                require(scene->property("energyFlowRunning").toBool()==(section==5),"energy flow follows current vehicle task");
                require(scene->findChild<QObject*>("chargingConnector")->property("plugged").toBool(),"ambient views retain actual connection");
                capture(QString("layout-vehicle-%1").arg(section));
                if(section==4||section==5){click("interiorView");require(!scene->property("energyFlowRunning").toBool()&&!scene->findChild<QObject*>("chargingConnector")->property("plugged").toBool(),"interior has no exterior energy decorations");capture(QString("layout-interior-%1").arg(section));click("exteriorView");}
            }
            for(int page=0;page<4;++page){
                const auto name=QString("tab%1").arg(page).toLatin1();click(name.constData());click("statusEnergyButton");
                require(window.property("page").toInt()==2&&item("chargeStart")&&state.parked()&&state.charging(),"global battery entry navigates without controlling charging");
            }
            control("faults",{{"pauseTelemetry",true}});wait([&]{return !state.externalReady();},"charging data stale",6000);require(!scene->property("energyFlowRunning").toBool()&&item("chargeStateLabel")->property("text")==QStringLiteral("车辆数据已过期"),"stale charging cannot display active flow");capture("energy-06-stale");click("tab0");require(item("homeEnergyRow")->property("chargeMode")=="stale","home expired summary");capture("home-energy-stale");click("homeViewCharging");require(!item("chargeStart")->isEnabled(),"offline details remain read only");control("faults",{{"pauseTelemetry",false}});wait([&]{return state.externalReady();},"charging data recovered",8000);require(scene->property("energyFlowRunning").toBool(),"confirmed charging restores flow");click("chargeStart");wait([&]{return !state.charging();},"pause before full SOC");
            control("soc",{{"value",100}});wait([&]{return state.batteryPercent()==100;},"full SOC");require(item("chargeStateLabel")->property("text")==QStringLiteral("电池已充满")&&!item("chargeStart")->isEnabled(),"full battery distinct from charging");capture("energy-07-full");click("tab0");require(item("homeEnergyRow")->property("chargeMode")=="full","home full summary");capture("home-energy-full");click("homeViewCharging");control("soc",{{"value",90}});wait([&]{return state.batteryPercent()==90;},"target SOC");require(item("chargeStateLabel")->property("text")==QStringLiteral("已达到充电目标"),"90 percent target does not claim full battery");capture("energy-08-target");click("tab0");require(item("homeEnergyRow")->property("chargeMode")=="target","home target reached summary");capture("home-energy-target");click("homeViewCharging");click("chargePlug");wait([&]{return !state.plugged();},"disconnect energy preview");click("chargePort");wait([&]{return !state.portOpen();},"close energy preview");
            control("startDriving");wait([&]{return state.speed()==40;},"resume before stale test");state.startNavigation(QStringLiteral("公司"));click("tab0");click("homeDriving");drive=item("drivingVehicleScene");QTest::qWait(350);const auto routeBeforeLoss=state.routeProgress();control("faults",{{"pauseTelemetry",true}});wait([&]{return !state.externalReady();},"stale telemetry disables control",6000);const auto staleSoc=state.batteryPercent();const auto frozen=drive->property("travelMeters").toDouble();QTest::qWait(220);require(drive->property("travelMeters").toDouble()==frozen,"stale data stops road and wheel animation");state.setWindow(0,100);require(state.batteryPercent()==staleSoc,"stale data retains last actual SOC");require(!item("driveGearD")->isEnabled(),"stale data disables remote driving controls");capture("07-data-stale");
            control("advance",{{"seconds",60}});control("faults",{{"pauseTelemetry",false}});wait([&]{return state.externalReady();},"fresh snapshot restores connection",8000);require(state.routeProgress()>routeBeforeLoss+0.06,"same session reconnect catches up travelled navigation distance");capture("08-reconnected");
            stopSimulator();wait([&]{return !state.externalReady();},"server process exit detected");simulator.start();require(simulator.waitForStarted(3000),"restart simulator");connectConsole();wait([&]{return state.externalReady()&&state.batteryPercent()>81.9;},"new simulator session full snapshot",8000);
            state.setVolume(51);click("sourceButton");click("sourceInternal");require(!state.externalMode()&&state.batteryPercent()==local["battery"].toDouble()&&state.windows()[0].toDouble()==local["windows"].toList()[0].toDouble(),"restore previous internal vehicle state");require(state.volume()==51,"source switch preserves local media preferences");click("closePopup");click("tab0");capture("09-internal-restored");
            require(warnings.isEmpty(),qPrintable(warnings.join('\n')));console.disconnect(&app);console.abort();stopSimulator();qInfo()<<"PASS dual-process link: telemetry, actual window motion, stop, all four windows, SOC/speed, charging to target, rejection, timeout, stale freeze, navigation catch-up, reconnect, process restart and internal restore";app.exit(0);
        }catch(const std::exception &error){window.grabWindow().save(directory+"/failure.png");qCritical()<<"LINK FAIL:"<<error.what();qCritical().noquote()<<simulator.readAllStandardError();console.disconnect(&app);console.abort();stopSimulator();app.exit(2);}
    });
}
